const urls = [ //array de las URL de ZOCO
  {
    url: "https://www.zocopagos.com/",
    seccion: "Inicio y Preguntas Frecuentes Generales"
  },
  {
    url: "https://organizador.zocotickets.com/terminos-y-condiciones-organizador",
    seccion: "Terminos y condiciones"
  },
    {
    url: "https://organizador.zocotickets.com/politica-de-privacidad",
    seccion: "Politica de Privacidad"
  },
   { url: "https://zocopagos.com/pagos/simulador#pagos-simulador", seccion: "Simulador de costos" },
];
// Mapeo y return de las URL en json


const script = `
(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));

  const titulos = [...document.querySelectorAll('*')].filter(el => {
    const t = (el.textContent || '').trim();
    if (!t.startsWith('¿')) return false;
    if (el.closest('a') || el.closest('footer')) return false;
    if ([...el.children].some(c => (c.textContent || '').trim().startsWith('¿'))) return false;
    return true;
  });

  const faqs = [];
  for (const t of titulos) {
    t.click();
    await sleep(800);
    const cont = t.closest('[class*="accordion"], [class*="faq"], [class*="item"], li') || t.parentElement;
    const pregunta = (t.innerText || '').trim();
    const bloque = (cont.innerText || '').trim();
    faqs.push({ pregunta, respuesta: bloque.replace(pregunta, '').trim() });
  }
  return faqs;
})()
`;
return urls.map(item => ({
  json: {
    url: item.url,
    seccion: item.seccion,
    body: JSON.stringify({
      url: item.url,
      formats: ["markdown"],
      onlyMainContent: false,
      waitFor: 4000,
      actions: [
        { type: "executeJavascript", script: script },
        { type: "wait", milliseconds: 1000 }
      ]
    })
  }
}));

// --- limpieza de markdown ---
function limpiar(txt) {
  return txt
    .replace(/!\[[^\]]*\]\([^)]*\)/g, '')        // imágenes (incluye data URIs)
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')     // links -> solo el texto
    .replace(/data:image\/[^\s)]+/g, '')         // restos de data URI sueltos
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// --- corta el footer antes de procesar (ahí viven los SVG codificados) ---
function cortarFooter(md) {
  const marcas = [
    'Preciso. Sencillo. Seguro.',
    'Copyright © ZOCO',
    '](https://www.facebook.com/'
  ];
  let fin = md.length;
  for (const m of marcas) {
    const i = md.indexOf(m);
    if (i !== -1 && i < fin) fin = i;
  }
  return md.slice(0, fin);
}

// --- detecta chunks que son basura URL-encoded ---
function esBasura(txt) {
  return (txt.match(/%/g) || []).length > 15;
}

const salida = [];

for (const item of $input.all()) {
  const d = item.json.data || {};
  const md = cortarFooter(d.markdown || '').trim();
  if (!md) continue;

  const url = d.metadata?.sourceURL || d.url || '';
  const seccion = item.json.seccion || d.metadata?.title || 'ZOCO';
  const esSimulador = /simulador/i.test(url);

  const aviso = esSimulador
    ? 'ADVERTENCIA OFICIAL: el simulador de ZOCO usa tasas únicamente de demostración. Los valores que muestra NO son las condiciones reales del comercio y no incluyen impuestos locales ni retenciones. Las tasas reales las define un asesor comercial según el plan, rubro y condiciones vigentes.\n\n'
    : '';

  // ---------- A) Preguntas frecuentes (home) ----------
  const inicio = md.indexOf('## Preguntasfrecuentes');
  if (inicio !== -1) {
    let bloque = md.slice(inicio + '## Preguntasfrecuentes'.length);
    const fin = bloque.indexOf('![App ZOCO');
    if (fin !== -1) bloque = bloque.slice(0, fin);

    const partes = bloque.split(/\n\s*\n/).map(p => p.trim()).filter(Boolean);
    const faqs = [];
    let actual = null;

    for (const p of partes) {
      const esPregunta = p.startsWith('¿') && p.endsWith('?') && !p.includes('\n');
      if (esPregunta) {
        actual = { pregunta: p, respuesta: [] };
        faqs.push(actual);
      } else if (actual) {
        actual.respuesta.push(p);
      }
    }

    for (const f of faqs) {
      const respuesta = limpiar(f.respuesta.join('\n\n'));
      if (respuesta.length < 20 || esBasura(respuesta)) continue;
      salida.push({
        json: {
          contenido: `${f.pregunta}\n\n${respuesta}`,
          tipo: 'faq',
          pregunta: f.pregunta,
          seccion,
          url
        }
      });
    }
    continue;
  }

  // ---------- D) FAQs sueltas (simulador: preguntas sin encabezado) ----------
  const partesGlobal = md.split(/\n\s*\n/).map(p => p.trim()).filter(Boolean);
  const hayPreguntas = partesGlobal.some(
    p => p.startsWith('¿') && p.endsWith('?') && !p.includes('\n')
  );

  if (hayPreguntas) {
    const faqs = [];
    let actual = null;

    for (const p of partesGlobal) {
      const esPregunta = p.startsWith('¿') && p.endsWith('?') && !p.includes('\n');
      if (esPregunta) {
        actual = { pregunta: p, respuesta: [] };
        faqs.push(actual);
      } else if (actual) {
        actual.respuesta.push(p);
      }
    }

    for (const f of faqs) {
      const respuesta = limpiar(f.respuesta.join('\n\n'));
      if (respuesta.length < 20 || esBasura(respuesta)) continue;
      salida.push({
        json: {
          contenido: `${f.pregunta}\n\n${aviso}${respuesta}`,
          tipo: esSimulador ? 'simulador' : 'faq',
          pregunta: f.pregunta,
          seccion,
          url
        }
      });
    }
    continue;
  }

  const primerH2 = md.indexOf('\n## ');

  // ---------- C) Páginas sin encabezados ni FAQs: un solo chunk ----------
  if (primerH2 === -1) {
    const texto = limpiar(md);
    if (texto.length >= 80 && /[a-záéíóúñ]{4,}/i.test(texto) && !esBasura(texto)) {
      salida.push({
        json: {
          contenido: `${seccion}\n\n${aviso}${texto}`,
          tipo: esSimulador ? 'simulador' : 'pagina',
          titulo: seccion,
          seccion,
          url
        }
      });
    }
    continue;
  }

  // ---------- B) Documentos legales: chunk por sección ----------
  const cuerpo = md.slice(primerH2);
  const secciones = cuerpo.split(/\n(?=##\s)/);

  for (const s of secciones) {
    const texto = limpiar(s);
    if (texto.length < 120) continue;
    if (!/[a-záéíóúñ]{4,}/i.test(texto)) continue;
    if (esBasura(texto)) continue;

    const lineas = texto.split('\n');
    const titulo = (lineas[0] || '').replace(/^#+\s*/, '').replace(/\\/g, '').trim();
    const resto = lineas.slice(1).join('\n').trim();
    if (!resto) continue;

    const MAX = 1200;
    const parrafos = resto.split(/\n\s*\n/);
    let buffer = '';

    const emitir = () => {
      if (!buffer.trim()) return;
      salida.push({
        json: {
          contenido: `${titulo}\n\n${buffer.trim()}`,
          tipo: 'documento',
          titulo,
          seccion,
          url
        }
      });
      buffer = '';
    };

    for (const p of parrafos) {
      if ((buffer + '\n\n' + p).length > MAX) emitir();
      buffer += (buffer ? '\n\n' : '') + p;
    }
    emitir();
  }
}

return salida;
